  'Is het kapot?': { ask: { fr: 'Ton collègue a fait une chute avec son vélo. Demande-lui si le vélo est cassé.', en: 'Your colleague fell off their bike. Ask whether the bike is broken.' }, need: [{ what: { fr: 'demande s’il est cassé', en: 'asks whether it is broken' }, any: ['kapot', 'stuk'], miss: 'Werkt je fiets nog?' }, { what: { fr: 'au moins 4 mots', en: 'at least 4 words' }, min: 4, miss: 'Kapot?' }], model: 'Is je fiets kapot?' },
  'Is het museum vandaag open?': { ask: { fr: 'Tu veux visiter le musée de la ville aujourd’hui. Demande à un passant si le musée est ouvert en ce moment.', en: 'You want to visit the town museum today. Ask a passer-by whether the museum is open right now.' }, need: [{ what: { fr: 'demande s’il est ouvert', en: 'asks whether it is open' }, any: ['open', 'geopend', 'gesloten', 'dicht'], miss: 'Waar is het museum, alstublieft?' }, { what: { fr: 'parle du musée', en: 'mentions the museum' }, any: ['museum'], miss: 'Is de bibliotheek nu open?' }, { what: { fr: 'au moins 4 mots', en: 'at least 4 words' }, min: 4, miss: 'Museum open?' }], model: 'Is het museum nu open, alstublieft?' },
