  'Jullie kunnen me geloven.': { ask: { fr: 'Tes collègues doutent que le projet sera prêt à temps. Rassure-les : dis-leur qu’ils peuvent te croire.', en: 'Your colleagues doubt that the project will be ready on time. Reassure them: tell them they can believe you.' }, need: [{ what: { fr: 'demande de te croire ou de te faire confiance', en: 'asks them to believe or trust you' }, any: ['geloven', 'geloof', 'vertrouwen', 'vertrouw', 'beloof', 'beloven'], miss: 'Het project is morgen klaar, echt waar.' }, { what: { fr: 'au moins 4 mots', en: 'at least 4 words' }, min: 4, miss: 'Ik beloof het.' }], model: 'Jullie kunnen mij zeker geloven, het is op tijd klaar.' },
  'Kan iemand helpen?': { ask: { fr: 'Ton ordinateur ne marche plus au bureau. Demande à voix haute si quelqu’un peut t’aider.', en: 'Your computer stops working at the office. Ask out loud whether someone can help you.' }, need: [{ what: { fr: 'demande de l’aide', en: 'asks for help' }, any: ['helpen', 'help', 'hulp'], miss: 'Is er iemand hier?' }, { what: { fr: 's’adresse à quelqu’un', en: 'addresses someone' }, any: ['iemand', 'iedereen', 'jullie', 'collega', 'wie', 'ge', 'gij', 'u', 'je', 'jij'], miss: 'Help, mijn laptop doet het niet.' }, { what: { fr: 'au moins 3 mots', en: 'at least 3 words' }, min: 3, miss: 'Iemand helpen?' }], model: 'Kan iemand mij helpen, alstublieft?' },
