  'Kunt u wat trager spreken, alstublieft?': { ask: { fr: 'Un collègue parle trop vite. Demande-lui poliment (vouvoiement) de parler plus lentement. Commence par « Kunt u ».', en: 'A colleague speaks too fast. Politely (formal) ask them to speak more slowly. Start with “Kunt u”.' }, need: [{ what: { fr: 'commence par « kunt u »', en: 'starts with “kunt u”' }, rx: /^\s*kunt\s+u\b/i, miss: 'Spreekt u trager, alstublieft?' }, { what: { fr: 'demande de parler plus lentement', en: 'asks for slower speech' }, any: ['trager'], miss: 'Kunt u spreken, alstublieft?' }, { what: { fr: 'au moins 4 mots', en: 'at least 4 words' }, min: 4, miss: 'Kunt u trager?' }], model: 'Kunt u trager spreken, alstublieft?' },
